let refresh: Promise<boolean> | null = null
const authChannel = new BroadcastChannel("auth")
function safeInternalPath(p: string) {
  return p.startsWith("/") && !p.startsWith("//") ? p : "/app"
}
export async function on401(ctx: { url: string; path: string; retry: () => Promise<unknown> }) {
  if (/\/api\/auth\/(login|logout|refresh)/.test(ctx.url)) throw new Error("auth-route-401")
  if (!refresh) {
    refresh = $fetch("/api/auth/refresh", { method: "POST" }).then(() => true).catch(() => false)
      .finally(() => { refresh = null })
  }
  if (await refresh) return ctx.retry()
  queryClient.clear()
  authChannel.postMessage({ type: "logout" })
  await navigateTo({ path: "/login", query: { redirect: safeInternalPath(ctx.path) } })
}

